'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={not_started:'Not started',todo:'To do',in_progress:'In progress',waiting:'Waiting / on hold',blocked:'Blocked',assigned:'Assigned',done:'Done'};
let inboxCollapsed=false;try{inboxCollapsed=localStorage.getItem('flowdesk-inbox-collapsed')==='true';}catch{}
let reportKind='daily',currentReport=null;
let state,view='today',day='',mode='board',filter='',typeFilter='all',statusFilter='open',selected=null,dragged=null,toastTimer,refreshing=false;
async function api(path,data){const r=await fetch('/api/'+path,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const v=await r.json();if(!r.ok)throw Error(v.error||'Something went wrong.');return v;}
function toast(message,error=false){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').className=error?'error':'';$('#toast').style.display='block';toastTimer=setTimeout(()=>$('#toast').style.display='none',5500);}
function connectionStatus(online){const el=$('#connection-status');if(el){el.textContent=online?'Saved locally':'Reconnecting…';el.classList.toggle('offline',!online);}}
async function refresh(renderView=true){if(refreshing)return;refreshing=true;try{state=await api('state'+(day?'?day='+encodeURIComponent(day):''));day=state.day;connectionStatus(true);if(view==='reports')currentReport=await api('report?kind='+reportKind+'&day='+encodeURIComponent(day));if(renderView)render();}catch(e){connectionStatus(false);toast(e.message,true);}finally{refreshing=false;}}
async function action(path,data,message){try{const result=await api(path,data);await refresh();if(message)toast(message);return result;}catch(e){toast(e.message,true);return null;}}
function duration(seconds){const m=Math.floor(seconds/60);return m>=60?`${Math.floor(m/60)}h ${m%60}m`:`${m}m`;}
function timer(t){const running=t.running_since?Math.max(0,(Date.now()-Date.parse(state.server_time))/1000):0;const sec=Math.floor(t.actual_seconds+running);return `${String(Math.floor(sec/3600)).padStart(2,'0')}:${String(Math.floor(sec/60)%60).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function dateLabel(d){return new Date(d+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});}
function timestamp(s){return s?new Date(s).toLocaleString('en-IN',{timeZone:state.settings.timezone,month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'—';}
function planTasks(){const source=day<state.today&&state.historical_tasks?state.historical_tasks.map(t=>({...t,actual_seconds:t.tracked_seconds,running_since:null})):state.tasks;return state.plans.map(p=>({...source.find(t=>t.id===p.task_id),plan:p})).filter(t=>t.id&&!t.archived&&t.kind!=='communication');}
function navigate(v){view=v;filter='';if(v==='communications'){day=state.today;statusFilter='open';}if(v==='reports'){if(day>state.today)day=state.today;render();refresh();}else render();}
function heading(title,subtitle,extra=''){return `<div class="page-heading"><div><p class="eyebrow">YOUR PERSONAL WORKSPACE</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${extra}</div>`;}
function dateNav(){return `<div class="date-nav"><button data-date="-1" aria-label="Previous day">‹</button><input aria-label="Plan date" id="plan-date" type="date" value="${day}" ${view==='reports'?`max="${state.today}"`:''}><button data-date="1" aria-label="Next day" ${view==='reports'&&day>=state.today?'disabled':''}>›</button><button data-date="today">Today</button></div>`;}
function metrics(items){const done=items.filter(t=>t.status==='done').length;const estimated=items.reduce((a,t)=>a+(t.plan?.estimate_minutes??t.estimate_minutes),0);const actual=items.reduce((a,t)=>a+t.actual_seconds,0);const running=state.tasks.filter(t=>t.status==='in_progress');return `<div class="summary"><div class="metric"><div class="label">Daily progress <span>↗</span></div><div class="value">${done} <em>/ ${items.length} tasks</em></div><div class="progress-line"><div style="--width:${items.length?done/items.length*100:0}%"></div></div></div><div class="metric"><div class="label">Planned time <span>◷</span></div><div class="value">${duration(estimated*60)}</div><small>${estimated>state.settings.daily_minutes?'Above your daily planning budget':duration(state.settings.daily_minutes*60)+' daily planning budget'}</small></div><div class="metric"><div class="label">Tracked task time <span>◴</span></div><div class="value">${duration(actual)}</div><small>${day<state.today?'Time recorded on this day':'Lifetime sessions for these tasks'}</small></div><div class="metric"><div class="label">Running now <span>⌁</span></div><div class="value">${running.length} <em>/ ${state.settings.total_limit} slots</em></div><small>${running.length?'A little momentum, in motion.':'Ready when you are.'}</small></div></div>`;}
function capacity(){const active=state.tasks.filter(t=>t.status==='in_progress');return `<div class="capacity"><strong>In progress limits</strong><button data-view="settings">Edit limits</button>${[['coding','Coding',state.settings.coding_limit],['admin','Admin & managerial',state.settings.admin_limit]].map(([k,n,limit])=>{const count=active.filter(t=>t.category===k).length;return `<div class="group">${n}<div class="slots">${Array.from({length:limit},(_,i)=>`<span class="slot ${i<count?'on':''}"></span>`).join('')}</div><span>${count}/${limit}</span></div>`;}).join('')}<small>Only In progress counts · across all days and Communications.</small></div><div class="running-items">${active.length?`<span>Using slots:</span> ${active.map(t=>`<button data-detail="${t.id}">${esc(t.title)}${t.kind==='communication'?' · Communication':''}</button>`).join('')}`:'<span>No running items. Waiting and blocked items use no slots.</span>'}</div>`;}
let holdContext=null;
function holdBadge(t){if(!['waiting','blocked','assigned'].includes(t.status))return '';return `<div class="hold-note ${t.status}"><strong>${t.status==='assigned'?'↗ Assigned · Follow-up':t.status==='waiting'?'Ⅱ Waiting / on hold':'! Blocked'}${(t.status==='assigned'?t.assignee:t.waiting_on)?' · '+esc(t.status==='assigned'?t.assignee:t.waiting_on):''}</strong>${t.waiting_note?`<span>${esc(t.waiting_note)}</span>`:''}</div>`;}
function holdButton(t){return t.archived||t.status==='done'||day<state.today?'':`<button type="button" class="hold-action" data-hold="${t.id}">${['waiting','blocked','assigned'].includes(t.status)?t.status==='assigned'?'Edit assignment':'Edit hold':'Hold / assign'}</button>`;}
function syncHoldState(){const f=$('#hold-form'),assigned=f.elements.status.value==='assigned';f.elements.assignee.required=assigned;$('#assignee-field').hidden=!assigned;$('#waiting-field').hidden=assigned;$('#hold-heading').textContent=assigned?'Assign to someone':'Put task on hold';f.querySelector('[type=submit]').textContent=assigned?'Assign & track follow-up':'Save status';}
async function openHold(id,status='waiting',placement=null){try{const d=await api('task?id='+id);holdContext={id,placement};const f=$('#hold-form');f.reset();f.elements.status.value=status;f.elements.waiting_on.value=d.task.waiting_on||'';f.elements.assignee.value=d.task.assignee||'';f.elements.waiting_note.value=d.task.waiting_note||'';$('#hold-error').textContent='';$('#hold-title').textContent=d.task.title;syncHoldState();$('#hold-dialog').showModal();(status==='assigned'?f.elements.assignee:f.elements.waiting_on).focus();}catch(e){toast(e.message,true);}}
function editButton(t){return `<button type="button" class="edit-task" data-edit="${t.id}" aria-label="Edit ${esc(t.title)}" title="Edit title and description">Edit</button>`;}
async function editTask(id){try{const result=await api('task?id='+id);if($('#detail-dialog').open)$('#detail-dialog').close();newTask(result.task);}catch(error){toast(error.message,true);}}
function card(t){return `<article class="card ${t.status==='in_progress'?'running':''} ${t.status==='done'?'completed':''}" draggable="${day>=state.today}" data-drag="${t.id}"><div class="card-top"><span class="tag ${t.category}">${t.category==='coding'?'⌘ Coding':'▧ Admin'}</span>${t.ai_enabled?'<span class="muted" title="AI enabled">✧</span>':''}<span class="priority ${t.priority}">${t.priority==='high'?'↑':t.priority==='medium'?'＝':'↓'} ${esc(t.priority)}</span>${editButton(t)}</div>${t.project_path?`<div class="project-label">${esc(t.project_path.split('/').pop())}</div>`:''}<button class="card-title" data-detail="${t.id}">${esc(t.title)}</button><div class="card-meta"><span>◷ ${duration(t.estimate_minutes*60)}</span><span>· ${t.duration_days} ${t.duration_days===1?'day':'days'}</span><span>· ${esc(t.difficulty)}</span></div>${t.plan?.rolled_from?`<div class="rollover">↪ Carried from ${esc(t.plan.rolled_from)}</div>`:''}${t.due_date?`<div class="rollover">${t.due_date<state.today&&t.status!=='done'?'Overdue · ':'Target · '}${esc(t.due_date)}</div>`:''}${holdBadge(t)}<div class="card-bottom">${holdButton(t)}<span class="time" ${t.status==='in_progress'?`data-timer="${t.id}"`:''}>${t.status==='in_progress'?timer(t):t.status==='done'?'✓ '+duration(t.actual_seconds):t.actual_seconds?'Paused · '+duration(t.actual_seconds):'Ready to start'}</span>${day!==state.today?'':t.status==='in_progress'?`<button data-status="todo" data-id="${t.id}">Ⅱ Pause</button><button data-status="done" data-id="${t.id}" aria-label="Finish ${esc(t.title)}">✓ Finish</button>`:t.status==='done'?`<button data-status="todo" data-id="${t.id}">Reopen</button>`:`<button data-status="in_progress" data-id="${t.id}">${t.status==='assigned'?'Take back & start':'▷ Start'}</button>`}</div></article>`;}
function baseTodayView(){const items=planTasks();return heading(day===state.today?'My day':dateLabel(day),day===state.today?`${dateLabel(day)} · Choose your priorities. Keep your focus.`:'Your daily commitments, preserved over time.',dateNav())+metrics(items)+capacity()+`<div class="section-head"><div><h3>Your daily plan <span class="badge">${items.length} tasks</span></h3><p>${day<state.today?'Saved end-of-day task states and plan order.':'Pick what matters. Put it in order. Get into flow.'}</p></div><div class="board-view-controls">${mode==='board'?'<div class="board-scroll-controls" aria-label="Scroll board"><button data-board-scroll="-1" aria-label="Scroll board left">←</button><button data-board-scroll="1" aria-label="Scroll board right">→</button></div>':''}<div class="view-tabs"><button data-mode="board" class="${mode==='board'?'active':''}">▦ Board</button><button data-mode="list" class="${mode==='list'?'active':''}">☰ Order</button></div></div></div>`+(mode==='board'?`<div class="board" data-drop="plan" tabindex="0" role="region" aria-label="Daily task board, scroll horizontally for more columns">${Object.entries(labels).map(([status,title])=>`<section class="column" data-drop="${day===state.today?status:'plan'}"><div class="column-head"><span class="dot ${status}"></span>${title}<span class="count">${items.filter(t=>t.status===status).length}</span>${day>=state.today?`<button class="icon" data-add="${status}" aria-label="Add task to ${title}">+</button>`:''}</div>${items.filter(t=>t.status===status).map(card).join('')||`<div class="empty-column"><span>${status==='done'?'✓':status==='in_progress'?'▷':'⋯'}</span>${status==='done'?'Completed tasks appear here.':status==='in_progress'?'Start a task to start its timer.':status==='todo'?'Queue your next task here.':status==='waiting'?'Your part is done. Waiting on someone else.':status==='assigned'?'Delegated work. Track who owns the next step.':status==='blocked'?'Work that needs an obstacle removed.':'Drop a task here to plan it.'}</div>`}${status==='not_started'&&day>=state.today?'<button class="add-column" data-pick>＋ Add from task inbox</button>':''}</section>`).join('')}</div>`:list(items,true))+`<div class="day-note"><span>↪</span> Unfinished commitments roll into the next day. Your history stays intact.</div>`;}
function list(items,ordered=false){if(!items.length)return `<div class="empty-state"><div class="empty-icon">▤</div><h2>${ordered?'A fresh page for your day.':'A clear mind starts here.'}</h2><p>${ordered?'Choose tasks from your inbox or capture something new.':'Capture the next thing you want to do.<br>Plan it for today when you’re ready.'}</p><button class="primary" data-new>＋ Add your first task</button>${ordered?' <button data-pick>Choose from inbox</button>':''}</div>`;return `<div class="task-list">${ordered?'<div class="list-head">Drag to reorder, or use the arrow buttons. This is your daily sequence.</div>':''}${items.map((t,i)=>`<div class="task-row" ${day>=state.today&&!t.archived?`draggable="true" data-drag="${t.id}" ${ordered?`data-order-target="${t.id}"`:''}`:''}><span class="${ordered?'order':'dot '+t.status}">${ordered?String(i+1).padStart(2,'0'):''}</span><div class="row-title"><button class="title" data-detail="${t.id}">${esc(t.title)}</button><small>${esc(labels[t.status])} · ${t.category==='coding'?'Coding':'Admin'} · ${esc(t.priority)} priority · ${t.duration_days} day${t.duration_days>1?'s':''}</small>${communicationContext(t)}${holdBadge(t)}</div><span class="row-meta">${duration(t.estimate_minutes*60)}</span><div class="actions">${editButton(t)}${holdButton(t)}${ordered&&day>=state.today?`<button data-move="-1" data-id="${t.id}" aria-label="Move task up" ${i===0?'disabled':''}>↑</button><button data-move="1" data-id="${t.id}" aria-label="Move task down" ${i===items.length-1?'disabled':''}>↓</button><button data-unplan="${t.id}" aria-label="Remove from plan">−</button>`:''}${!ordered&&t.kind!=='communication'&&day>=state.today&&!t.archived&&t.status!=='done'&&!state.plans.some(p=>p.task_id===t.id)?`<button data-plan="${t.id}">＋ ${day===state.today?'Today':'Plan'}</button>`:''}${t.archived?`<button data-restore="${t.id}">Restore</button>`:day!==state.today?'':t.status==='in_progress'?`<button data-status="todo" data-id="${t.id}">Pause</button><button data-status="done" data-id="${t.id}">Finish</button>`:t.status!=='done'?`<button data-status="in_progress" data-id="${t.id}">${t.status==='assigned'?'Take back & start':'▷ Start'}</button>`:''}</div></div>`).join('')}</div>`;}
function baseInboxView(){let items=state.tasks.filter(t=>t.kind!=='communication').filter(t=>view==='inbox'?!t.archived&&t.status!=='done'&&!state.plans.some(p=>p.task_id===t.id):statusFilter==='archived'?t.archived:!t.archived&&(statusFilter==='all'||(statusFilter==='open'?t.status!=='done':t.status==='done')));items=items.filter(t=>(typeFilter==='all'||t.category===typeFilter)&&(t.title+' '+t.description).toLowerCase().includes(filter.toLowerCase()));return heading(view==='inbox'?'Task inbox':'All tasks',view==='inbox'?'One place for every idea, task, and loose end. Pick what belongs in your day.':'All your work, from the first thought to the final checkmark.',view==='inbox'?dateNav():'')+`<form class="capture" id="quick-capture"><input name="title" aria-label="Quick capture task" placeholder="Something on your mind? Add a task…" maxlength="300" required><button type="button" data-new>More details</button><button class="primary">＋ Capture task</button></form><div class="filters"><input id="search" aria-label="Search tasks" placeholder="⌕ Search your tasks" value="${esc(filter)}"><select id="type-filter" aria-label="Filter work type"><option value="all">All work types</option><option value="coding" ${typeFilter==='coding'?'selected':''}>Coding</option><option value="admin" ${typeFilter==='admin'?'selected':''}>Admin / managerial</option></select>${view==='all'?`<select id="status-filter" aria-label="Filter status"><option value="open" ${statusFilter==='open'?'selected':''}>Open tasks</option><option value="done" ${statusFilter==='done'?'selected':''}>Completed</option><option value="all" ${statusFilter==='all'?'selected':''}>All statuses</option><option value="archived" ${statusFilter==='archived'?'selected':''}>Archived</option></select>`:''}</div><div class="section-head"><h3>${view==='inbox'?'Ready to be planned':'Your tasks'} <span class="badge">${items.length}</span></h3><span class="muted">${day===state.today?'Today':esc(day)}</span></div>${list(items)}`;}
function inboxTasks(){return state.tasks.filter(t=>t.kind!=='communication'&&!t.archived&&t.status!=='done'&&!state.plans.some(p=>p.task_id===t.id)).filter(t=>(typeFilter==='all'||t.category===typeFilter)&&(t.title+' '+t.description).toLowerCase().includes(filter.toLowerCase()));}

function communicationContext(t){if(t.kind!=='communication'&&!t.related_task_id)return '';const parent=state.tasks.find(x=>x.id===t.related_task_id);return `<div class="communication-context">${t.contact?`<span>↔ ${esc(t.contact)}</span>`:''}${t.due_date?`<span>${t.due_date<state.today&&t.status!=='done'?'Overdue':'Follow up'} · ${esc(t.due_date)}</span>`:''}${parent?`<button data-detail="${parent.id}">Related: ${esc(parent.title)}</button>`:''}</div>`;}
function communicationsView(){const items=state.tasks.filter(t=>t.kind==='communication'&&(statusFilter==='archived'?t.archived:!t.archived&&(statusFilter==='all'||(statusFilter==='open'?t.status!=='done':t.status==='done')))).filter(t=>(t.title+' '+t.description+' '+t.contact).toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')||a.id-b.id);return heading('Communications','Messages, handoffs, and follow-ups. Keep the conversation work in one place.', '<button class="primary" data-new>＋ Add communication</button>')+`<div class="panel"><p>Use Waiting when you have sent your message and need a reply. Link a communication to the task it helps unblock. Completing a follow-up leaves the related task’s status for you to decide.</p></div><div class="filters"><input id="search" aria-label="Search communications" placeholder="Search by person, message, or notes" value="${esc(filter)}"><select id="status-filter" aria-label="Filter status"><option value="open" ${statusFilter==='open'?'selected':''}>Open communications</option><option value="done" ${statusFilter==='done'?'selected':''}>Completed</option><option value="all" ${statusFilter==='all'?'selected':''}>All statuses</option><option value="archived" ${statusFilter==='archived'?'selected':''}>Archived</option></select></div><div class="section-head"><h3>${items.length} communications</h3><span class="muted">Ordered by follow-up date · Set Target date when editing</span></div>`+(items.length?list(items):'<div class="empty-state"><h2>No communications here yet.</h2><p>Add a message, call, or follow-up, or change an existing task’s Item type to Communication.</p><button class="primary" data-new>＋ Add communication</button></div>');}

function historyStrip(){const days=(state.history_days||[]).filter(d=>view!=='reports'||d.day<=state.today).slice(0,14);return days.length?`<div class="history-strip"><span>DAY HISTORY</span>${days.map(d=>`<button data-day="${d.day}" class="${d.day===day?'selected':''}">${new Date(d.day+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}<small>${d.count} tasks</small></button>`).join('')}</div>`:'';}
function dayCapture(){return `<form class="day-capture" id="day-capture"><span aria-hidden="true">＋</span><input name="title" aria-label="Quickly add a task" placeholder="Add a task without leaving your day…" maxlength="300" required><select name="destination" aria-label="Task destination"><option value="inbox">To inbox</option><option value="day" ${day<state.today?'disabled':''}>To this day</option></select><button class="primary">Add task <span aria-hidden="true">↵</span></button></form>`;}
function inboxRail(){const tasks=inboxTasks();if(inboxCollapsed)return `<aside class="inbox-rail collapsed" data-drop="inbox"><button id="toggle-inbox" aria-expanded="false" aria-label="Expand task inbox">▤<span>Task inbox</span><b>${tasks.length}</b>›</button></aside>`;return `<aside class="inbox-rail" data-drop="inbox"><div class="rail-head"><h3>▤ Task inbox <span class="badge">${tasks.length}</span></h3><button id="toggle-inbox" class="icon" aria-expanded="true" aria-label="Collapse task inbox">‹</button></div><p class="rail-help">Drag a task into your daily plan.<br>Drag it back here to unplan it.</p><button class="add-column" data-new>＋ Capture a task</button><div class="rail-tasks">${tasks.map(t=>`<article class="inbox-item" draggable="${day>=state.today}" data-drag="${t.id}"><div><span class="tag ${t.category}">${t.kind==='issue'?'Issue':t.category==='coding'?'Coding':'Admin'}</span><span class="priority ${t.priority}">${esc(t.priority)}</span>${editButton(t)}</div>${t.project_path?`<div class="project-label">${esc(t.project_path.split('/').pop())}</div>`:''}<button class="card-title" data-detail="${t.id}">${esc(t.title)}</button><div class="card-meta">${duration(t.estimate_minutes*60)} · ${t.duration_days} days${t.project_path?' · '+esc(t.project_path.split('/').pop()):''}</div>${holdBadge(t)}${holdButton(t)}${day>=state.today?`<button class="inbox-add" data-plan="${t.id}" aria-label="Add ${esc(t.title)} to daily plan">＋ Add to day</button>`:''}</article>`).join('')||'<div class="empty-column">Your inbox is clear.<br>Capture something whenever it comes to mind.</div>'}</div></aside>`;}
function todayView(){let html=baseTodayView();const start=html.indexOf('<div class="section-head">');return html.slice(0,start)+historyStrip()+dayCapture()+`<div class="planner-layout ${inboxCollapsed?'inbox-collapsed':''}">${inboxRail()}<div class="daily-plan-surface" data-drop="plan">${html.slice(start)}</div></div>`;}
function inboxView(){const html=baseInboxView();if(view!=='inbox')return html;const split=html.indexOf('<div class="section-head">');return html.slice(0,split)+historyStrip()+`<div class="inbox-daily-layout"><section class="inbox-list-surface" data-drop="inbox">${html.slice(split)}</section><section class="daily-list-panel" data-drop="plan"><div class="section-head"><div><p class="eyebrow">DAILY PLAN</p><h3>${day===state.today?'Today':dateLabel(day)}</h3><p>Drop tasks here, then put them in order.</p></div><span class="badge">${planTasks().length}</span></div>${list(planTasks(),true)}</section></div>`;}
function reportsView(){const r=currentReport;const fresh=r&&r.kind===reportKind&&(reportKind==='daily'?r.start===day:r.start<=day&&r.end>=day);const top=heading('Daily & weekly reports','Daily snapshots close at midnight. Weekly reports close after Sunday.',dateNav())+`<div class="section-head"><div class="view-tabs"><button data-report-kind="daily" class="${reportKind==='daily'?'active':''}">Daily report</button><button data-report-kind="weekly" class="${reportKind==='weekly'?'active':''}">Weekly report</button></div>${fresh?`<a class="button" href="/api/report?kind=${reportKind}&day=${day}&format=markdown" download="flowdesk-${reportKind}-${r.start}.md">↓ Download report</a>`:''}</div>`+historyStrip();if(!fresh)return top+'<div class="panel"><p>Loading your report…</p></div>';const m=r.summary;return top+`<div class="report-banner"><div><strong>${r.start}${r.end!==r.start?' → '+r.end:''}</strong><small>${esc(r.timezone)} · Generated ${timestamp(r.generated_at)}</small></div><span class="badge">${r.finalized?'✓ Saved final report':'◷ Live draft'}</span></div><div class="summary"><div class="metric"><div class="label">Completed / planned</div><div class="value">${m.completed} <em>/ ${m.planned}</em></div><small>${reportKind==='weekly'?'Unique tasks across the week':'Includes work completed outside the plan'}</small></div><div class="metric"><div class="label">Carrying forward</div><div class="value">${m.carried_forward}</div><small>Unfinished daily commitments</small></div><div class="metric"><div class="label">Tracked task time</div><div class="value">${duration(m.task_seconds)}</div><small>Parallel sessions count separately</small></div><div class="metric"><div class="label">Active clock time</div><div class="value">${duration(m.active_seconds)}</div><small>Overlapping sessions counted once</small></div></div>${reportKind==='weekly'?`<div class="panel"><h3>The week at a glance</h3><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Day</th><th>Planned</th><th>Done</th><th>Carried</th><th>Task time</th></tr></thead><tbody>${r.days.map(d=>`<tr><td><button data-report-day="${d.start}">${dateLabel(d.start)}</button></td><td>${d.summary.planned}</td><td>${d.summary.completed}</td><td>${d.summary.carried_forward}</td><td>${duration(d.summary.task_seconds)}</td></tr>`).join('')}</tbody></table></div></div>`:''}<div class="panel"><h3>${reportKind==='weekly'?'Completed tasks this week':'Daily task record'}</h3><p>${m.estimate_ratio===null?'Finish a task to compare its original estimate with its lifetime tracked time.':`Completed work took ${m.estimate_ratio.toFixed(2)}× its original estimate (${duration(m.completed_actual_seconds)} actual / ${duration(m.original_completed_minutes*60)} estimated).`}</p><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Task</th><th>State at close</th><th>Estimated</th><th>${reportKind==='weekly'?'Time on completion day':'Time this day'}</th></tr></thead><tbody>${r.tasks.map(t=>`<tr><td><button class="card-title" data-detail="${t.id}">${esc(t.title)}</button><small>${t.planned?'Planned':'Unplanned activity'}${t.project_path?' · '+esc(t.project_path.split('/').pop()):''}${t.carried_forward?' · Carried forward':''}</small>${editButton(t)}</td><td>${esc(labels[t.status])}${holdBadge(t)}</td><td>${duration(t.original_estimate_minutes*60)}</td><td>${duration(t.tracked_seconds)}</td></tr>`).join('')||'<tr><td colspan="4">No recorded work for this period.</td></tr>'}</tbody></table></div></div><div class="panel"><h3>Saved reports</h3><div class="report-archive">${(state.report_archive||[]).map(a=>`<button data-open-report="${a.kind}" data-period="${a.period_start}">${a.kind==='daily'?'◫':'▦'} ${a.period_start} <small>${a.kind}</small></button>`).join('')||'<p>Your first report will be saved when a day closes. Today’s report stays live until then.</p>'}</div></div>`;}
function dailyTime(){const tz=state.settings.timezone;const fmt=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'});const dayOf=ms=>{const p=Object.fromEntries(fmt.formatToParts(new Date(ms)).map(p=>[p.type,p.value]));return `${p.year}-${p.month}-${p.day}`;};let low=Date.parse(day+'T00:00:00Z')-86400000,high=low+3*86400000;for(let n=0;n<40;n++){const mid=(low+high)/2;if(dayOf(mid)<day)low=mid;else high=mid;}const begin=Math.ceil(high);low=begin;high=begin+2*86400000;for(let n=0;n<40;n++){const mid=(low+high)/2;if(dayOf(mid)<=day)low=mid;else high=mid;}const end=Math.ceil(high);const ranges=state.sessions.map(s=>[Math.max(begin,Date.parse(s.started_at)),Math.min(end,s.ended_at?Date.parse(s.ended_at):Date.now())]).filter(([a,b])=>b>a).sort((a,b)=>a[0]-b[0]);let total=0,union=0,lastA=null,lastB=null;for(const [a,b]of ranges){total+=b-a;if(lastA===null){lastA=a;lastB=b;}else if(a<=lastB)lastB=Math.max(lastB,b);else{union+=lastB-lastA;lastA=a;lastB=b;}}if(lastA!==null)union+=lastB-lastA;return {total:total/1000,union:union/1000};}
function insightsView(){const done=state.tasks.filter(t=>t.status==='done'&&!t.archived);const estimated=done.reduce((a,t)=>a+t.original_estimate_minutes,0),actual=done.reduce((a,t)=>a+t.actual_seconds/60,0);const time=dailyTime();const max=Math.max(1,...done.flatMap(t=>[t.original_estimate_minutes,t.actual_seconds/60]));return heading('Insights','Better estimates begin with honest data. A little reflection goes a long way.',dateNav())+`<div class="summary"><div class="metric"><div class="label">Completed tasks · all time</div><div class="value">${done.length}</div><small>Every finish is a data point.</small></div><div class="metric"><div class="label">Actual / original estimate</div><div class="value">${estimated?(actual/estimated).toFixed(2)+'×':'—'}</div><small>${estimated?'Completed tasks only':'Complete a task to see a comparison'}</small></div><div class="metric"><div class="label">Task time · selected day</div><div class="value">${duration(time.total)}</div><small>Parallel sessions count separately</small></div><div class="metric"><div class="label">Active window · selected day</div><div class="value">${duration(time.union)}</div><small>Overlapping sessions counted once</small></div></div><div class="panel"><h3>Expectation meets reality.</h3><p>Original estimate <span class="badge">light green</span> versus tracked task time <span class="badge">dark green</span>. Estimates remain preserved when you revise a task.</p>${done.length?done.slice(0,20).map(t=>`<div class="chart-row"><button class="card-title" data-detail="${t.id}">${esc(t.title)}</button><div class="chart-bars"><div class="bar" style="--width:${t.original_estimate_minutes/max*100}%"></div><div class="bar actual" style="--width:${t.actual_seconds/60/max*100}%"></div></div><small>${duration(t.original_estimate_minutes*60)} → ${duration(t.actual_seconds)}</small></div>`).join(''):'<div class="empty-column">Finish your first task to start seeing patterns here.</div>'}</div><div class="two-cols"><div class="panel"><h3>By work type</h3>${['coding','admin'].map(c=>{const ts=done.filter(t=>t.category===c),e=ts.reduce((a,t)=>a+t.original_estimate_minutes,0),a=ts.reduce((a,t)=>a+t.actual_seconds/60,0);return `<div class="event"><strong>${c==='coding'?'Coding':'Admin & managerial'}</strong><div>${ts.length} completed<small>${e?(a/e).toFixed(2)+'× estimated time':'Not enough data yet'}</small></div></div>`;}).join('')}</div><div class="panel"><h3>What these numbers mean</h3><p>Task time measures how long a task runs, including unattended AI work. The active window measures clock time with at least one timer running. Neither claims to measure your personal attention.</p><p>Pauses are excluded from tracked time. Start-to-finish cycle time includes pauses. Original estimates, revisions, sessions, and daily snapshots are retained for future AI analytics.</p></div></div>`;}
function eventName(e){const detail=JSON.parse(e.detail);if(e.kind==='comment_added')return 'Status comment · '+(labels[detail.status]||detail.status)+': '+detail.text;if(e.kind==='status_changed')return `${labels[detail.from]} → ${labels[detail.to]}`;return ({subissues_reordered:'Resolution steps reordered',created:'Task captured',edited:'Task details updated',planned:'Added to daily plan',rolled_over:'Carried into next day',unplanned:'Removed from daily plan',archived:'Task archived',restored:'Task restored',settings_updated:'Workspace settings updated',plan_reordered:'Daily sequence updated',ai_suggested:'AI suggestion received'})[e.kind]||e.kind;}
function eventsHtml(events){return events.map(e=>`<div class="event"><time>${timestamp(e.at)}</time><div>${esc(eventName(e))}<small>${esc(state.tasks.find(t=>t.id===e.task_id)?.title||'Workspace')}${JSON.parse(e.detail).day?' · '+esc(JSON.parse(e.detail).day):''}</small></div></div>`).join('')||'<p class="subtitle">Your story starts with your first task.</p>';}
function activityView(){return heading('Activity log','Captures, starts, pauses, finishes, and changes. The latest 300 workspace events.')+`<div class="panel">${eventsHtml(state.events)}</div>`;}
function settingsView(){const s=state.settings;return heading('Workspace settings','Your capacity, your daily rhythm, and your optional AI connection.')+`<div class="service-banner"><span class="service-indicator"></span><div><strong>${state.service?.managed?'Starts automatically when you log in':'Running locally'}</strong><small>${state.service?.managed?'Flowdesk runs in the background. You can close the browser anytime.':'Your tasks are saved on this Mac.'}</small></div><a class="button" href="/guide.html" target="_blank" rel="noopener">Claude MCP guide ↗</a></div><form id="settings-form" class="settings-form"><div class="panel"><h3>Work in parallel, with intention.</h3><div class="form-grid"><label>Coding slots (1–5)<input name="coding_limit" type="number" min="1" max="5" value="${s.coding_limit}" required></label><label>Admin & communication slots (1–5)<input name="admin_limit" type="number" min="1" max="5" value="${s.admin_limit}" required></label><label>Total running slots (1–5)<input name="total_limit" type="number" min="1" max="5" value="${s.total_limit}" required></label><label>Daily planning budget (minutes)<input name="daily_minutes" type="number" min="30" max="1440" value="${s.daily_minutes}" required></label><label>Timezone<input name="timezone" value="${esc(s.timezone)}" required></label></div><p>Only In progress items use running slots, including Communications. Not started, To do, Waiting, Blocked, Assigned, and Done do not count. Planning has no task-count limit. Category limits share the total running limit (up to 5). Timers stop when you pause, hold, block, or finish an item.</p></div><div class="panel"><h3>✧ Gemini task rewriting</h3><label>Gemini model ID<input name="ai_model" value="${esc(s.ai_model)}" required></label><p>Phase one rewrites the selected task using its title, description, and type only. No project files, MCP tools, other tasks, or conversations are sent. Estimates and priority stay unchanged.</p></div><button class="primary">Save workspace settings</button></form><form id="api-key-form" class="panel" style="margin-top:24px;max-width:850px"><h3>Your Gemini API key <span class="badge">${state.ai_ready?'Key configured (not verified)':'Not connected'}</span></h3><p>${state.ai_key_source==='environment'?'Using GEMINI_API_KEY from the server environment.':'Keys entered here stay only in server memory and are cleared on restart.'} The key is never saved in the task database or included in exports. Gemini usage is billed to your Google account.</p><label>API key<input name="key" type="password" autocomplete="off" spellcheck="false" required minlength="10" maxlength="256" placeholder="Paste your Gemini API key"></label><p id="api-key-error" role="alert"></p><div class="detail-actions"><button class="primary" type="submit">Save key for this session</button><button type="button" id="remove-api-key" ${state.ai_ready?'':'disabled'}>Remove / disconnect key</button><a class="button" href="https://aistudio.google.com/apikey" target="_blank" rel="noopener noreferrer">Get a Gemini key ↗</a></div></form><div class="panel" style="max-width:850px"><h3>Phase two · Project MCP context</h3><p>Planned: connect a read-only MCP server for your project so AI can ask about architecture and code before proposing better scope and tasks. This is not connected or available yet.</p></div><div class="panel" style="margin-top:24px;max-width:850px"><h3>Your data stays with you.</h3><p>Tasks, daily plans, timer sessions, estimates, and history are stored in local SQLite. Export a complete JSON snapshot for analysis or archival.</p><div class="detail-actions"><button id="export-data">↓ Export all data</button></div></div>`;}
function render(){if(!state)return;const boardScroll=$('.board')?.scrollLeft||0;const names={today:'My day',inbox:'Task inbox',all:'All tasks',communications:'Communications',insights:'Insights',activity:'Activity log',trash:'Trash',settings:'Settings',reports:'Reports'};$('#breadcrumb').innerHTML=`Workspace <span>/</span> ${names[view]}`;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#inbox-count').textContent=state.tasks.filter(t=>t.kind!=='communication'&&!t.archived&&t.status!=='done'&&!state.plans.some(p=>p.task_id===t.id)).length;$('#view').innerHTML=({today:todayView,inbox:inboxView,all:inboxView,communications:communicationsView,insights:insightsView,activity:activityView,trash:trashView,settings:settingsView,reports:reportsView})[view]();const board=$('.board');if(board)board.scrollLeft=boardScroll;}
function syncTaskKind(){const f=$('#task-form'),communication=f.elements.kind.value==='communication',editing=!!f.elements.id.value;$$('[data-communication-field]').forEach(el=>el.hidden=!communication);$('#plan-check').hidden=editing||communication;if(communication){f.elements.category.value='admin';f.elements.plan_today.checked=false;}$('#task-heading').textContent=editing?(communication?'Edit communication':'Edit task'):(communication?'New communication':'New task');f.querySelector('[type=submit]').textContent=editing?'Save changes':communication?'Save communication':'Save task ↗';}
function newTask(task=null,column=null){const form=$('#task-form');form.reset();form.elements.initial_status.value=!task&&column&&day===state.today?column:'not_started';$('#new-assignee-field').hidden=!!task||form.elements.initial_status.value!=='assigned';form.elements.assignee.required=!$('#new-assignee-field').hidden;$('#new-task-destination').textContent=column?'Add to '+(day===state.today?labels[column]:'the selected day’s Not started column'):'';$('#task-error').textContent='';form.elements.related_task_id.innerHTML='<option value="">No related task</option>'+state.tasks.filter(t=>t.id!==task?.id&&t.kind!=='communication').map(t=>`<option value="${t.id}">#${t.id} · ${esc(t.title)}</option>`).join('');if(!task&&view==='communications'){form.elements.kind.value='communication';form.elements.category.value='admin';form.elements.estimate_minutes.value=15;}form.elements.id.value=task?.id||'';$('#task-heading').textContent=task?'Edit task':'New task';form.querySelector('[type=submit]').textContent=task?'Save changes':'Save task ↗';$('#plan-check').hidden=!!task;for(const k of ['title','description','category','priority','difficulty','estimate_minutes','duration_days','due_date','project_path','kind','contact','related_task_id','assignee'])if(task)form.elements[k].value=task[k]??'';form.elements.ai_enabled.checked=!!task?.ai_enabled;form.elements.plan_today.checked=!task&&view==='today';$('#plan-day-label').textContent=day<=state.today?'Add to today’s plan':'Add to '+day+' plan';syncTaskKind();$('#task-dialog').showModal();form.elements.title.focus();}
function subissuesHtml(children,t){const done=children.filter(c=>c.status==='done').length;return `<section class="subissue-tracker"><div class="section-head"><h3>Resolution tracker</h3><span class="badge">${done} / ${children.length} complete</span></div><p class="subtitle">Break this down into work, communication, and the next step. Reorder as needed; each step keeps its own status and history.</p><div class="progress-line"><div style="--width:${children.length?done/children.length*100:0}%"></div></div><div class="subissue-list">${children.map((c,i)=>`<article class="subissue-row"><span class="order">${i+1}</span><div class="subissue-main"><button data-detail="${c.id}">${esc(c.title)}</button><small>${c.kind==='communication'?'↔ Communication':c.kind==='issue'?'Issue':'Task'} · ${esc(labels[c.status])}${c.assignee?' · '+esc(c.assignee):''}${c.contact?' · '+esc(c.contact):''}</small></div><div class="actions"><button data-child-move="-1" data-child="${c.id}" data-parent="${t.id}" aria-label="Move ${esc(c.title)} up" ${i===0?'disabled':''}>↑</button><button data-child-move="1" data-child="${c.id}" data-parent="${t.id}" aria-label="Move ${esc(c.title)} down" ${i===children.length-1?'disabled':''}>↓</button><button data-child-status="${c.status==='done'?'todo':'done'}" data-child="${c.id}" data-parent="${t.id}">${c.status==='done'?'Reopen':'✓ Complete'}</button></div></article>`).join('')||'<p class="subtitle">No steps yet. Add the first thing needed to resolve this issue.</p>'}</div><form id="subissue-form"><input type="hidden" name="parent_id" value="${t.id}"><div class="form-grid"><label>Next step<input name="title" maxlength="300" required placeholder="What needs to happen?"></label><label>Step type<select name="kind"><option value="task">Task — work to do</option><option value="communication">Communication — ask or follow up</option><option value="issue">Subissue — needs investigation</option></select></label></div><label>Notes<textarea name="description" rows="2" maxlength="20000" placeholder="Details or the question to ask"></textarea></label><label>Person / team (optional)<input name="contact" maxlength="300" placeholder="Who is involved?"></label><p id="subissue-error" role="alert"></p><button class="primary" type="submit">＋ Add step</button></form><small>Completing steps does not automatically close this issue. Work steps can be planned from Task inbox; communication steps also appear in Communications.</small></section>`;}
function commentsHtml(comments,t){return `<section class="status-comments"><h3>Status comments <span class="badge">${comments.length}</span></h3><p class="subtitle">Add a progress update, decision, or next step. Each comment records the task’s status at that time.</p><form id="comment-form"><input type="hidden" name="task_id" value="${t.id}"><label for="status-comment">New status comment</label><textarea id="status-comment" name="text" rows="3" maxlength="5000" required placeholder="What changed? What happens next?"></textarea><p id="comment-error" role="alert"></p><button class="primary" type="submit">Add comment</button></form><div class="comment-list">${comments.map(c=>`<article class="status-comment"><div><time>${timestamp(c.at)}</time><span class="badge">${esc(labels[c.status]||c.status)}</span></div><p>${esc(c.text)}</p></article>`).join('')||'<p class="subtitle">No status comments yet.</p>'}</div></section>`;}
function trashView(){const items=state.deleted_tasks||[];return heading('Trash','Deleted tasks and communications. Restore an item to use it again.')+`<div class="panel"><p>Deleting stops running timers. Task history and recorded time are retained for reports.</p>${items.length?items.map(t=>`<div class="event"><div><strong>${esc(t.title)}</strong><small>Deleted ${timestamp(t.deleted_at)}</small></div><button data-undelete="${t.id}">Restore task</button></div>`).join(''):'<p>Trash is empty.</p>'}<p id="trash-error" role="alert"></p></div>`;}
function openDelete(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;$('#delete-title').textContent=t.title;$('#delete-error').textContent='';$('#confirm-delete').dataset.id=id;$('#delete-dialog').showModal();}
let detailNavigation=[];
function taskNavigation(id){if(!$('#detail-dialog').open){detailNavigation=[...new Set($$('#view [data-detail]').map(b=>Number(b.dataset.detail)))];if(!detailNavigation.includes(id))detailNavigation=state.tasks.map(t=>t.id);}detailNavigation=detailNavigation.filter(tid=>state.tasks.some(t=>t.id===tid));if(!detailNavigation.includes(id))detailNavigation=state.tasks.map(t=>t.id);const index=detailNavigation.indexOf(id);return `<div class="task-navigation"><button type="button" data-detail="${detailNavigation[index-1]||''}" ${index<=0?'disabled':''} aria-label="Previous task" title="Previous task">←</button><span>${index+1} / ${detailNavigation.length}</span><button type="button" data-detail="${detailNavigation[index+1]||''}" ${index<0||index>=detailNavigation.length-1?'disabled':''} aria-label="Next task" title="Next task">→</button></div>`;}
async function detail(id){try{const d=await api('task?id='+id),t=state.tasks.find(x=>x.id===id);selected=id;const cycle=t.first_started_at?duration(((t.finished_at?Date.parse(t.finished_at):Date.now())-Date.parse(t.first_started_at))/1000):'—';$('#detail').innerHTML=`<div class="dialog-top"><div><p class="eyebrow">${(t.kind||'task').toUpperCase()} #${t.id} · ${esc(labels[t.status])}</p><h2>${esc(t.title)}</h2></div>${taskNavigation(id)}<button class="icon close-dialog" aria-label="Close">×</button></div><div class="detail-facts"><div><small>Original estimate</small><strong>${duration(t.original_estimate_minutes*60)}</strong></div><div><small>Current estimate</small><strong>${duration(t.estimate_minutes*60)}</strong></div><div><small>Tracked task time</small><strong data-timer="${t.id}">${timer(t)}</strong></div><div><small>First started</small><strong>${timestamp(t.first_started_at)}</strong></div><div><small>Finished</small><strong>${timestamp(t.finished_at)}</strong></div><div><small>Cycle time (incl. pauses)</small><strong>${cycle}</strong></div></div>${t.project_path?`<p class="subtitle">Project · ${esc(t.project_path)}</p>`:''}<div class="detail-notes">${esc(t.description||'No additional notes yet.')}</div>${communicationContext(t)}${holdBadge(t)}<div class="detail-actions">${t.kind!=='communication'?`<button data-followup="${t.id}">＋ Communication / follow-up</button>`:''}${!t.archived&&t.status!=='done'?`<button class="primary" data-assign="${t.id}">${t.status==='assigned'?'Reassign / follow up':'Assign to someone'}</button>`:''}${holdButton(t)}<button data-edit="${t.id}">Edit details</button>${!t.archived?`<select data-status-select="${t.id}" aria-label="Task status">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${t.status===k?'selected':''}>${v}</option>`).join('')}</select><button data-ai-toggle="${t.id}">✧ AI ${t.ai_enabled?'on':'off'}</button>${t.ai_enabled?`<button data-ai="${t.id}">Preview task for AI</button>`:''}<button data-archive="${t.id}">Archive</button>`:`<button data-restore="${t.id}">Restore</button>`}<button class="danger" data-delete="${t.id}">Delete task</button></div>${d.suggestions.length?`<div class="panel"><h3>Latest AI suggestion</h3>${suggestionHtml(JSON.parse(d.suggestions[0].content))}<button data-apply-saved="${d.suggestions[0].id}">Apply suggested details</button></div>`:''}${subissuesHtml(d.subissues||[],t)}${commentsHtml(d.comments||[],t)}<h3>Timer sessions</h3><div class="history">${d.sessions.length?d.sessions.map(s=>`<div class="event"><div>${timestamp(s.started_at)} → ${s.ended_at?timestamp(s.ended_at):'Running'}<small>${duration(((s.ended_at?Date.parse(s.ended_at):Date.now())-Date.parse(s.started_at))/1000)}</small></div></div>`).join(''):'<p class="subtitle">Start this task to record your first session.</p>'}</div><h3 style="margin-top:24px">Task history</h3><div class="history">${eventsHtml(d.events)}</div>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}catch(e){toast(e.message,true);}}
function suggestionHtml(s){return `<div class="suggestion"><p class="detail-notes">${esc(s.description)}</p><p class="subtitle">Suggested title: ${esc(s.title||'Unchanged')}</p>${[['steps','Suggested steps'],['acceptance_criteria','Definition of done'],['risks','Risks & assumptions']].map(([k,v])=>`<h3>${v}</h3><ul>${s[k].map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`).join('')}</div>`;}
let currentPreview,currentSuggestion;
async function previewAI(id){try{const p=await api('ai-preview',{id});currentPreview={...p,id};$('#ai-content').innerHTML=`<div class="dialog-top"><div><p class="eyebrow">TASK ONLY · REVIEW BEFORE SENDING</p><h2>Improve this task with Gemini.</h2></div><button class="icon close-dialog" aria-label="Close">×</button></div><p class="subtitle">No project context · ${esc(p.model)}</p><div class="warning">Only the task below will be sent to Google when you click “Send to Gemini.” Check that it contains no secrets or sensitive information. No code or project MCP is accessed.</div><pre class="context">${esc(JSON.stringify(p.payload,null,2))}</pre><div class="form-bottom"><span>${state.ai_ready?'Suggestions will be reviewed before applying.':'Add your Gemini API key in Settings to connect.'}</span><button class="primary" id="send-ai" ${state.ai_ready?'':'disabled'}>Send to Gemini ↗</button></div>`;$('#ai-dialog').showModal();}catch(e){toast(e.message,true);}}
async function applySuggestion(s){const t=state.tasks.find(t=>t.id===selected);const notes=[s.description,'Steps:',...s.steps.map(x=>'• '+x),'Definition of done:',...s.acceptance_criteria.map(x=>'• '+x),'Risks & assumptions:',...s.risks.map(x=>'• '+x)].join('\n');const r=await action('update',{id:selected,title:s.title||t.title,description:(t.description?t.description+'\n\n':'')+notes},'Suggested details applied. Original estimate preserved.');if(r){$('#ai-dialog').close();await detail(selected);}}
async function reorder(id,beforeId=null,delta=0){const visible=planTasks().map(t=>t.id);const ids=state.plans.map(p=>p.task_id);const index=ids.indexOf(id);if(index<0)return;const target=beforeId?ids.indexOf(beforeId):ids.indexOf(visible[visible.indexOf(id)+delta]);if(target<0||target>=ids.length)return;ids.splice(index,1);ids.splice(target,0,id);await action('reorder',{day,ids},'Daily order saved.');}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.delete)return openDelete(+d.delete);if(d.undelete){b.disabled=true;try{await api('restore-deleted',{id:+d.undelete});await refresh();toast('Task restored.');}catch(error){$('#trash-error').textContent=error.message;}finally{b.disabled=false;}return;}if(b.id==='confirm-delete'){b.disabled=true;try{await api('delete',{id:+d.id,confirmed:true});$('#delete-dialog').close();$('#detail-dialog').close();await refresh();toast('Task moved to Trash.');}catch(error){$('#delete-error').textContent=error.message;}finally{b.disabled=false;}return;}if(b.id==='remove-api-key'){try{await api('ai-key',{remove:true});await refresh();toast('AI disconnected. No saved session key remains.');}catch(error){$('#api-key-error').textContent=error.message;}return;}if(d.boardScroll){const board=$('.board');if(board)board.scrollBy({left:Number(d.boardScroll)*252,behavior:'smooth'});return;}if(d.assign)return openHold(+d.assign,'assigned');if(d.childStatus){const result=await action('status',{id:+d.child,status:d.childStatus},'Step updated.');if(result)await detail(+d.parent);return;}if(d.childMove){try{const result=await api('task?id='+d.parent);const ids=result.subissues.map(t=>t.id),i=ids.indexOf(+d.child),j=i+(+d.childMove);if(i<0||j<0||j>=ids.length)return;[ids[i],ids[j]]=[ids[j],ids[i]];const saved=await action('reorder-subissues',{id:+d.parent,ids});if(saved)await detail(+d.parent);}catch(error){toast(error.message,true);}return;}if(b.classList.contains('close-dialog'))return b.closest('dialog').close();if(b.id==='toggle-inbox'){inboxCollapsed=!inboxCollapsed;try{localStorage.setItem('flowdesk-inbox-collapsed',String(inboxCollapsed));}catch{}return render();}if(d.day){day=d.day;return refresh();}if(d.reportKind){reportKind=d.reportKind;return refresh();}if(d.reportDay){day=d.reportDay;reportKind='daily';return refresh();}if(d.openReport){reportKind=d.openReport;day=d.period;return refresh();}if(d.view)return navigate(d.view);if(d.new!==undefined||b.id==='new-task')return newTask();if(d.mode){mode=d.mode;return render();}if(d.date){if(d.date==='today')day='';else{const dt=new Date(day+'T12:00:00Z');dt.setUTCDate(dt.getUTCDate()+Number(d.date));day=dt.toISOString().slice(0,10);}return refresh();}if(d.hold){const task=state.tasks.find(t=>t.id===+d.hold);return openHold(+d.hold,['waiting','blocked','assigned'].includes(task.status)?task.status:'waiting');}if(d.detail)return detail(+d.detail);if(d.followup){const t=state.tasks.find(t=>t.id===+d.followup);if($('#detail-dialog').open)$('#detail-dialog').close();newTask();const f=$('#task-form');f.elements.kind.value='communication';f.elements.category.value='admin';f.elements.estimate_minutes.value=15;f.elements.related_task_id.value=t.id;f.elements.contact.value=t.waiting_on||'';f.elements.title.value='Follow up: '+t.title;f.elements.description.value=t.waiting_note||'';f.elements.plan_today.checked=false;syncTaskKind();return;}if(d.edit)return editTask(+d.edit);if(d.status){const r=await action('status',{id:+d.id,status:d.status},d.status==='in_progress'?'Timer started.':d.status==='done'?'Task finished. Nicely done.':'Task updated.');if(r&&$('#detail-dialog').open)detail(+d.id);return;}if(d.plan)return action('plan',{id:+d.plan,day},'Added to your daily plan.');if(d.unplan)return action('unplan',{id:+d.unplan,day},'Removed from this day. Task stays in your list.');if(d.pick!==undefined){if(day<state.today)day=state.today;return navigate('inbox');}if(d.add!==undefined)return newTask(null,d.add);if(d.move)return reorder(+d.id,null,+d.move);if(d.archive){const r=await action('archive',{id:+d.archive},'Archived. You can restore it from All tasks.');if(r)$('#detail-dialog').close();return;}if(d.restore){await action('archive',{id:+d.restore,archived:false},'Task restored.');if($('#detail-dialog').open)detail(+d.restore);return;}if(d.aiToggle){const t=state.tasks.find(t=>t.id===+d.aiToggle);await action('update',{id:t.id,ai_enabled:!t.ai_enabled});return detail(t.id);}if(d.ai)return previewAI(+d.ai);if(d.applySaved){const v=await api('task?id='+selected);return applySuggestion(JSON.parse(v.suggestions.find(x=>x.id===+d.applySaved).content));}if(b.id==='send-ai'){b.disabled=true;b.textContent='Rewriting with Gemini…';try{const result=await api('ai-enrich',{id:currentPreview.id,token:currentPreview.token});currentSuggestion=result.suggestion;$('#ai-content').innerHTML=`<div class="dialog-top"><div><p class="eyebrow">AI SUGGESTION · YOUR CALL</p><h2>A clearer next step.</h2></div><button class="icon close-dialog" aria-label="Close">×</button></div>${suggestionHtml(currentSuggestion)}<div class="form-bottom"><span>Updates the title and appends notes. Estimates stay unchanged.</span><button class="primary" id="apply-ai">Apply suggested details</button></div>`;await refresh();}catch(error){toast(error.message,true);b.textContent='Close and review context again';}return;}if(b.id==='apply-ai')return applySuggestion(currentSuggestion);if(b.id==='export-data'){try{const data=await api('export');const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download='flowdesk-'+state.today+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Data exported.');}catch(error){toast(error.message,true);}}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const formId=form.getAttribute('id');const data=Object.fromEntries(new FormData(form));if(formId==='api-key-form'){const button=form.querySelector('[type=submit]');button.disabled=true;try{await api('ai-key',{key:data.key});form.reset();await refresh();toast('Key configured for this server session. It will be checked on your first AI request.');}catch(error){$('#api-key-error').textContent=error.message;}finally{button.disabled=false;}return;}if(formId==='subissue-form'){const button=form.querySelector('[type=submit]');button.disabled=true;$('#subissue-error').textContent='';try{const parent=state.tasks.find(t=>t.id===+data.parent_id);await api('create',{title:data.title,description:data.description,kind:data.kind,contact:data.contact,related_task_id:+data.parent_id,project_path:parent.project_path||'',category:data.kind==='communication'?'admin':parent.category,estimate_minutes:data.kind==='communication'?15:60});await refresh();await detail(+data.parent_id);toast('Step added to the resolution tracker.');}catch(error){$('#subissue-error').textContent=error.message;}finally{button.disabled=false;}return;}if(formId==='comment-form'){const button=form.querySelector('[type=submit]');button.disabled=true;$('#comment-error').textContent='';try{await api('comment',{id:+data.task_id,text:data.text});await refresh();await detail(+data.task_id);toast('Status comment added.');}catch(error){$('#comment-error').textContent=error.message;}finally{button.disabled=false;}return;}if(formId==='hold-form'){const button=form.querySelector('[type=submit]');button.disabled=true;const payload={...(holdContext.placement||{id:holdContext.id}),status:data.status,waiting_on:data.waiting_on,waiting_note:data.waiting_note,assignee:data.assignee};try{await api(holdContext.placement?'place':'status',payload);await refresh();$('#hold-dialog').close();if($('#detail-dialog').open)await detail(holdContext.id);toast(data.status==='assigned'?'Assigned. Track this in the Assigned column.':'Status saved.');}catch(error){$('#hold-error').textContent=error.message;}finally{button.disabled=false;}return;}if(formId==='task-form'){const payload={...data,related_task_id:data.related_task_id?Number(data.related_task_id):null,estimate_minutes:+data.estimate_minutes,duration_days:+data.duration_days,ai_enabled:form.elements.ai_enabled.checked};if(data.id)payload.id=+data.id;else{delete payload.id;if(data.kind!=='communication'&&form.elements.plan_today.checked)payload.day=day>=state.today?day:state.today;}const b=form.querySelector('[type=submit]');b.disabled=true;$('#task-error').textContent='';try{await api(data.id?'update':'create',payload);await refresh();$('#task-dialog').close();toast(data.id?'Task updated.':'Task captured.');}catch(error){$('#task-error').textContent=error.message;}finally{b.disabled=false;}}if(formId==='day-capture'){const payload={title:data.title};if(data.destination==='day'&&day>=state.today)payload.day=day;const result=await action('create',payload,'Task captured.');if(result)$('#day-capture input').focus();}if(formId==='quick-capture'){const r=await action('create',{title:data.title},'Captured in your inbox.');if(r)$('#quick-capture input').focus();}if(formId==='settings-form'){for(const k of ['coding_limit','admin_limit','total_limit','daily_minutes'])data[k]=+data[k];await action('settings',data,'Workspace settings saved.');}});
document.addEventListener('change',async e=>{if(e.target.matches('#hold-form [name=status]'))syncHoldState();if(e.target.matches('#task-form [name=kind]'))syncTaskKind();if(e.target.id==='plan-date'){day=e.target.value||state.today;await refresh();}if(e.target.id==='type-filter'){typeFilter=e.target.value;render();}if(e.target.id==='status-filter'){statusFilter=e.target.value;render();}if(e.target.dataset.statusSelect){if(['waiting','blocked','assigned'].includes(e.target.value)){const status=e.target.value;const id=+e.target.dataset.statusSelect;e.target.value=state.tasks.find(t=>t.id===id).status;return openHold(id,status);}await action('status',{id:+e.target.dataset.statusSelect,status:e.target.value});detail(+e.target.dataset.statusSelect);}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;filter=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
document.addEventListener('dragstart',e=>{const item=e.target.closest('[data-drag]');if(item){dragged=+item.dataset.drag;e.dataTransfer.setData('text/plain',String(dragged));e.dataTransfer.effectAllowed='move';}});
document.addEventListener('dragover',e=>{const col=e.target.closest('[data-drop],[data-order-target]');if(col&&dragged&&day>=state.today){e.preventDefault();col.classList.add('dragover');}});
document.addEventListener('dragleave',e=>e.target.closest('[data-drop],[data-order-target]')?.classList.remove('dragover'));
async function dropTask(id,kind,beforeId=null){if(day<state.today)return;const planned=state.plans.some(p=>p.task_id===id);if(kind==='inbox'){if(planned)return action('unplan',{id,day},'Returned to the inbox.');return;}const payload={id,day};if(beforeId)payload.before_id=beforeId;if(kind!=='plan')payload.status=kind;if(['waiting','blocked','assigned'].includes(kind))return openHold(id,kind,payload);return action('place',payload,kind==='in_progress'?'Added to the plan and timer started.':'Daily plan updated.');}
document.addEventListener('drop',async e=>{e.preventDefault();$$('.dragover').forEach(x=>x.classList.remove('dragover'));const target=e.target.closest('[data-drop],[data-order-target]');if(!target||!dragged||day<state.today)return;const id=dragged;dragged=null;return dropTask(id,target.dataset.orderTarget?'plan':target.dataset.drop,target.dataset.orderTarget?+target.dataset.orderTarget:null);});
document.addEventListener('dragend',()=>{dragged=null;$$('.dragover').forEach(x=>x.classList.remove('dragover'));});
document.addEventListener('keydown',e=>{if(e.metaKey||e.ctrlKey||e.altKey||e.target.matches('input,textarea,select')||$('dialog[open]'))return;if(e.key.toLowerCase()==='n'){e.preventDefault();newTask();}if(e.key.toLowerCase()==='d')navigate('today');});
setInterval(()=>{$$('[data-timer]').forEach(el=>{const t=state?.tasks.find(t=>t.id===+el.dataset.timer);if(t)el.textContent=timer(t);});},1000);
setInterval(async()=>{if(!state||$('dialog[open]')||document.activeElement?.matches('input,textarea,select')||dragged||view==='settings')return;const oldToday=state.today;await refresh(false);if(day===oldToday&&state.today!==oldToday)day=state.today;await refresh();},30000);
refresh();
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'flowdesk_list_tasks',description:'Read current local tasks and daily plan.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>{await refresh();return {tasks:state.tasks,plans:state.plans};}},{name:'flowdesk_capture_task',description:'Create a task in the local inbox without starting it or contacting AI.',inputSchema:{type:'object',properties:{title:{type:'string'}},required:['title'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!input||typeof input.title!=='string')throw Error('A title is required.');const r=await api('create',{title:input.title});await refresh();return r;}}]){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
